    actual fun getLinkPins(linkId: Long, startPinId: LongArray?, endPinId: LongArray?): Boolean {
        val a1 = if (startPinId == null) 0 else imguiKmpMalloc(startPinId.size * 8)
        if (startPinId != null) imguiKmpSetHeapI32(a1, IntArray(startPinId.size * 2) { i -> val value = startPinId[i / 2]; if (i % 2 == 0) value.toInt() else (value shr 32).toInt() }.toInt32Array())
        val a2 = if (endPinId == null) 0 else imguiKmpMalloc(endPinId.size * 8)
        if (endPinId != null) imguiKmpSetHeapI32(a2, IntArray(endPinId.size * 2) { i -> val value = endPinId[i / 2]; if (i % 2 == 0) value.toInt() else (value shr 32).toInt() }.toInt32Array())
        try {
            return ne_get_link_pins(linkId.toInt(), a1, a2) != 0
        } finally {
            if (startPinId != null) for (i in startPinId.indices) startPinId[i] = imguiKmpReadI32(a1, i * 2).toUInt().toLong() or (imguiKmpReadI32(a1, i * 2 + 1).toLong() shl 32)
            if (endPinId != null) for (i in endPinId.indices) endPinId[i] = imguiKmpReadI32(a2, i * 2).toUInt().toLong() or (imguiKmpReadI32(a2, i * 2 + 1).toLong() shl 32)
            if (startPinId != null) imguiKmpFree(a1)
            if (endPinId != null) imguiKmpFree(a2)
        }
    }
